const PREFIX = `lupe-${new URL(self.registration.scope).pathname}-`;
const CACHE = `${PREFIX}${VERSION}`;
const base = self.registration.scope;
let download;

async function broadcast(data) {
  const clients = await self.clients.matchAll({ includeUncontrolled: true, type: 'window' });
  clients.forEach(client => client.postMessage(data));
}

async function valid(response, asset) {
  if (!response?.ok || response.type === 'opaque') return false;
  const digest = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer());
  const hash = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
  return hash === asset.hash;
}

async function verify() {
  const cache = await caches.open(CACHE);
  for (const asset of ASSETS) if (!await valid(await cache.match(new URL(asset.path, base)), asset)) return false;
  return true;
}

async function downloadAssets() {
  const cache = await caches.open(CACHE);
  for (let i = 0; i < ASSETS.length; i++) {
    const asset = ASSETS[i];
    const url = new URL(asset.path, base);
    if (!await valid(await cache.match(url), asset)) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 20000);
      try {
        const response = await fetch(url, { cache: 'no-store', signal: controller.signal });
        if (!await valid(response, asset)) throw new Error(`Incomplete resource: ${asset.path}`);
        await cache.put(url, response);
      } finally { clearTimeout(timer); }
    }
    await broadcast({ type: 'DOWNLOAD_PROGRESS', progress: Math.round((i + 1) / ASSETS.length * 100) });
  }
  if (!await verify()) throw new Error('Incomplete cache');
}

function prepare() {
  if (!download) download = downloadAssets().finally(() => { download = null; });
  return download;
}

self.addEventListener('install', event => {
  // A failed install never takes over from the previous complete worker.
  // Completed updates remain waiting until all tabs close or the home screen asks.
  event.waitUntil(prepare().catch(async error => { await caches.delete(CACHE); throw error; }));
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  const reply = data => event.ports[0]?.postMessage(data);
  event.waitUntil((async () => {
    try {
      if (event.data?.type === 'VERIFY') reply({ ready: await verify(), version: VERSION });
      if (event.data?.type === 'REPAIR') { await prepare(); reply({ ready: await verify() }); }
      if (event.data?.type === 'ACTIVATE_UPDATE') {
        const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
        const others = clients.filter(client => client.id !== event.source?.id);
        if (others.length) { reply({ blocked: true }); return; }
        if (!await verify()) { reply({ blocked: true }); return; }
        reply({ blocked: false });
        await self.skipWaiting();
      }
    } catch { reply({ ready: false, error: 'download-failed' }); }
  })());
});

// Safari requests audio byte ranges. Serve them from the complete local file.
async function rangedResponse(response, range) {
  const buffer = await response.arrayBuffer();
  const size = buffer.byteLength;
  const match = /^bytes=(\d*)-(\d*)$/.exec(range);
  if (!match || (!match[1] && !match[2])) return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
  const start = match[1] ? Number(match[1]) : Math.max(0, size - Number(match[2]));
  const end = match[1] ? Math.min(match[2] ? Number(match[2]) : size - 1, size - 1) : size - 1;
  if (start >= size || end < start) return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
  const headers = new Headers(response.headers);
  headers.set('Content-Range', `bytes ${start}-${end}/${size}`);
  headers.set('Content-Length', String(end - start + 1));
  headers.set('Accept-Ranges', 'bytes');
  return new Response(buffer.slice(start, end + 1), { status: 206, headers });
}

self.addEventListener('fetch', event => {
  const { request } = event;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin || !url.href.startsWith(base)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const isEntry = request.mode === 'navigate' && (url.pathname === new URL(base).pathname || url.pathname === new URL('index.html', base).pathname);
    const cached = await cache.match(isEntry ? new URL('index.html', base) : request.url);
    if (cached) return request.headers.has('range') ? rangedResponse(cached, request.headers.get('range')) : cached;
    return fetch(request);
  })());
});
